// Order-8 IIR, ONE combinational sum (one multiply+add per stage, so the
// register-to-register critical path is independent of the order -> high Fmax)
// TRANSPOSED feedforward chain: one multiply+add per stage, followed by an
// identical chain in reverse order (the same function, different
// performance characteristics). Same critical path as the direct form.
module iir8_v7 (
  input clk, input rst_n, input [7:0] x, output reg [15:0] y
);
  reg [15:0] y2;
  reg [31:0] acc0;
  reg [31:0] acc1;
  reg [31:0] acc2;
  reg [31:0] acc3;
  reg [31:0] acc4;
  reg [31:0] acc5;
  reg [31:0] acc6;
  reg [31:0] acc7;
  reg [31:0] acc8;
  reg [15:0] y1;
  always @(posedge clk) begin
    if (!rst_n) begin
      y<=0; y1<=0; y2<=0; acc0<=0; acc1<=0; acc2<=0; acc3<=0; acc4<=0; acc5<=0; acc6<=0; acc7<=0; acc8<=0;
    end else begin
      acc0 <= 57*x + ((9*y)>>4) + ((5*y1)>>4);
      acc1 <= 40*x + acc0;
      acc2 <= 15*x + acc1;
      acc3 <= 4*x + acc2;
      acc4 <= 33*x + acc3;
      acc5 <= 61*x + acc4;
      acc6 <= 39*x + acc5;
      acc7 <= 57*x + acc6;
      acc8 <= 30*x + acc7;
      y <= acc8 & 16'hFFFF;
      y1 <= y;
      y2 <= y1;
    end
  end
endmodule
